"use client";

/**
 * Cards orbit an ellipse in faux-3D — swinging to the front they scale up, sharpen and stack forward; passing behind they shrink, dim and blur. Drag to spin with momentum; it drifts on its own when idle.
 */

import { useEffect, useRef } from "react";

// Flat, high-contrast swatches: a solid fill, one hard-edged motif, and a text colour that reads on it.
const SWATCHES = [
  { bg: "#ff5f1f", ink: "#151515", motif: "conic-gradient(at 62.5% 37.5%, #f6a8f2 25%, transparent 0) 0 0 / 32px 32px" },
  { bg: "#2d4bff", ink: "#ffffff", motif: "linear-gradient(90deg, #9dbbff 2px, transparent 0) 0 0 / 44px 44px, linear-gradient(#9dbbff 2px, transparent 0) 0 0 / 44px 44px" },
  { bg: "#f6a8f2", ink: "#151515", motif: "repeating-radial-gradient(circle at 30% 70%, #ff5f1f 0 12px, transparent 12px 34px)" },
  { bg: "#ffb000", ink: "#151515", motif: "repeating-linear-gradient(45deg, #151515 0 9px, transparent 9px 30px)" },
  { bg: "#6b3ce6", ink: "#ffffff", motif: "radial-gradient(circle, #ffb000 0 7px, transparent 7.5px) 0 0 / 36px 36px" },
  { bg: "#9dbbff", ink: "#151515", motif: "repeating-linear-gradient(0deg, #2d4bff 0 6px, transparent 6px 22px)" },
];

// Eight cards on six swatches: the two repeats sit opposite each other on the orbit, and light and dark fills alternate.
const CARDS = [
  { title: "Meridian", swatch: 0 },
  { title: "Sable", swatch: 4 },
  { title: "Juniper", swatch: 2 },
  { title: "Cobalt", swatch: 1 },
  { title: "Marrow", swatch: 3 },
  { title: "Fenn", swatch: 4 },
  { title: "Isohel", swatch: 5 },
  { title: "Vesper", swatch: 1 },
];

const C = {
  rx: 330, // ellipse half-width (px)
  ry: 78, // ellipse half-height (px)
  cw: 190, // card width (px)
  ch: 250, // card height (px)
  drift: 0.0026, // idle spin (rad/frame)
};

const OrbitCarousel = () => {
  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);

  useEffect(() => {
    const N = CARDS.length;

    let rot = 0;
    let vel = 0;
    let dragging = false;
    let lastX = 0;

    const layout = () => {
      for (let i = 0; i < N; i++) {
        const el = cardRefs.current[i];
        if (!el) continue;
        const theta = (i / N) * Math.PI * 2 + rot;
        const x = Math.sin(theta) * C.rx;
        const d = Math.cos(theta); // 1 = front of the orbit, -1 = back
        const y = d * C.ry;
        const near = (d + 1) / 2;
        el.style.transform = `translate3d(${x}px, ${y}px, 0) scale(${0.5 + near * 0.6})`;
        el.style.zIndex = String(Math.round(near * 200));
        el.style.opacity = String(0.35 + near * 0.65);
        el.style.filter = `blur(${(1 - near) * 2}px) brightness(${0.65 + near * 0.35})`;
      }
    };

    let raf = 0;
    const tick = () => {
      raf = requestAnimationFrame(tick);
      if (!dragging) {
        rot += vel + C.drift;
        vel *= 0.95; // momentum decays back to the idle drift
      }
      layout();
    };
    tick();

    const onDown = (e: PointerEvent) => {
      dragging = true;
      vel = 0;
      lastX = e.clientX;
      (e.target as HTMLElement).setPointerCapture?.(e.pointerId);
    };
    const onMove = (e: PointerEvent) => {
      if (!dragging) return;
      const dx = e.clientX - lastX;
      lastX = e.clientX;
      const dRot = dx * 0.0045;
      rot += dRot;
      vel = dRot; // released velocity = last frame's spin
    };
    const onUp = () => {
      dragging = false;
    };

    const scene = cardRefs.current[0]?.closest("[data-orbit]");
    scene?.addEventListener("pointerdown", onDown as EventListener);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);

    return () => {
      cancelAnimationFrame(raf);
      scene?.removeEventListener("pointerdown", onDown as EventListener);
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
  }, []);

  return (
    <div
      data-orbit
      className="relative flex h-[80vh] w-full cursor-grab select-none items-center justify-center overflow-hidden active:cursor-grabbing"
    >
      <div className="relative">
        {CARDS.map((card, i) => {
          const swatch = SWATCHES[card.swatch];
          return (
            <div
              key={card.title}
              ref={(el) => {
                cardRefs.current[i] = el;
              }}
              className="absolute overflow-hidden rounded-xl ring-1 ring-white/25"
              style={{
                width: C.cw,
                height: C.ch,
                marginLeft: -C.cw / 2,
                marginTop: -C.ch / 2,
                willChange: "transform, opacity, filter",
                background: `${swatch.motif}, ${swatch.bg}`,
                color: swatch.ink,
              }}
            >
              <p
                className="pointer-events-none absolute bottom-2 left-2 rounded-md px-2 py-1 text-[11px] font-medium uppercase tracking-widest"
                style={{ backgroundColor: swatch.bg }}
              >
                {card.title}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default OrbitCarousel;
